contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address sender) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(sender != address(0), "sender zero");

        uint256 balBefore = c.balances(sender); if (__ESBMC_reverted()) return;
        uint256 contractBalBefore = address(c).balance;

        c.Deposit{value: 0}(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == contractBalBefore && c.balances(sender) == balBefore);
    }

    receive() external payable {}
}

