// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(address sender) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(sender != address(0));
        uint256 balBefore;
        try c.balances(sender) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 contractBalBefore = address(c).balance;
        try c.Deposit{value: 0}() {} catch { return; }
        assertTrue(address(c).balance == contractBalBefore && c.balances(sender) == balBefore);
    }

    function testFuzz_run(address sender) public {
        vm.assume(sender.code.length == 0 && uint160(sender) > 0xffff && sender != address(this) && sender != address(c) && sender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && sender != 0x000000000000000000636F6e736F6c652e6c6f67 && sender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && sender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(sender);
    }

    receive() external payable {}
}
